import importlib
import subprocess
import six
import re
import logging
import time
import json
from functools import wraps
from taf.ue.rpc.mtk.server.message import LogCollectorFacade  # must use absolute import to make it runnable remotely


def raw_string_args_forced(func):
    def _covert_unicode_to_str(arg):
        return r"{}".format(arg) if (arg and isinstance(arg, type(u""))) else arg

    @wraps(func)
    def wrapped(self, *args, **kwargs):
        arg_list = [_covert_unicode_to_str(arg) for arg in list(args)]
        kwarg_dic = {k: _covert_unicode_to_str(v) for k, v in kwargs.items()}
        return func(self, *arg_list, **kwarg_dic)
    return wrapped


class MTKServer(object):

    def __init__(self):
        self.mace = importlib.import_module("mace")
        self.device = None
        self._connect_device_command = ""
        self._log_collector_facade = None

    def get_platform_information(self):
        return json.loads(self.device.platform_info)

    @raw_string_args_forced
    def connect_device(self, edb_file_path, com):
        self.device = self.mace.connect_device(com, database=edb_file_path)

    def collect_ota_message_until(self, expected, wait_timeout=5):
        logging.warning("this function will be deprecated after v1.0.0")
        start_time = time.time()

        itemset = self.mace.create_itemset(self.device)
        itemset.subscribe_ota()
        wait_timeout_ms = wait_timeout * 1000

        item = itemset.get_next_item(wait_timeout_ms)
        message = ""
        while True:
            if item:
                message += item.message

            if expected in message:
                break

            item = itemset.get_next_item(wait_timeout_ms)

            if (time.time() - start_time) > wait_timeout:
                break
        return message

    def collect_ota_json_message_unitl(self, expected, wait_timeout=5):
        logging.warning("this function will be deprecated after v1.0.0")
        start_time = time.time()

        itemset = self.mace.create_itemset(self.device)
        itemset.subscribe_ota()
        wait_timeout_ms = wait_timeout * 1000

        item = itemset.get_next_item(wait_timeout_ms)
        message_json = ""
        while True:
            if item:
                message_json = item.ota_json
            if expected in message_json:
                break

            item = itemset.get_next_item(wait_timeout_ms)

            if (time.time() - start_time) > wait_timeout:
                break
        return message_json

    def disconnect_device(self):
        self.device = None

    @raw_string_args_forced
    def send_at_command(self, cmd):
        return self.device.send_at_command(cmd)

    @raw_string_args_forced
    def inject_message(self, message_id, src_module, dest_module, sap, local_param):
        local_param = self._convert_field_type_to_raw_str(local_param)
        return self.device.inject_message(message_id,
                                          src_module,
                                          dest_module,
                                          sap,
                                          local_param,
                                          None)

    def _convert_field_type_to_raw_str(self, param):
        new_param = {}
        for key, value in param.items():
            if self._is_input_a_unicode_string(key):
                key = r"{}".format(key)
            if self._is_input_a_unicode_string(value):
                value = r"{}".format(value)
            new_param[key] = value
        return new_param

    @staticmethod
    def _is_input_a_unicode_string(input_string):
        return isinstance(input_string, type(u""))

    @raw_string_args_forced
    def set_filter(self, filter_name):
        self.device.set_filter(filter_name)
        self._log_collector_facade = LogCollectorFacade(self.device)

    @raw_string_args_forced
    def save_elg_log(self, output_path):
        if not output_path:
            logging.error("output path for the elg log was not specified")
        else:
            self.device.save(output_path)
            self._log_collector_facade.clear_collector_alias_store()

    def ports_ready(self, port_names):
        default_port_names = [('USB Application Port',
                               'USB Speech Port',
                               'USB META Port',
                               'USB Debug Port',
                               'USB Modem Port'), ]
        port_names = port_names or default_port_names
        port_info = WindowsMTKPNPCOM()
        return port_info.ports_ready(port_names)

    def set_log_collector_start_timestamp(self):
        self._log_collector_facade.set_start_timestamp()

    def read_ota_text_message_until(self, alias, expected_content, timeout):
        if not self._log_collector_facade:
            logging.error("you should call set_filter firstly")
            return
        return self._log_collector_facade.read_ota_text_message_until(alias_name=alias,
                                                                      expected_content=expected_content,
                                                                      timeout=timeout)

    def read_latest_ota_text_message(self, alias):
        if not self._log_collector_facade:
            logging.error("you should call set_filter firstly")
            return
        return self._log_collector_facade.read_latest_ota_text_message(alias)

    def read_ota_json_message_until(self, alias, expected_content, timeout):
        if not self._log_collector_facade:
            logging.error("you should call set_filter firstly")
            return
        return self._log_collector_facade.read_ota_json_message_until(alias_name=alias,
                                                                      expected_content=expected_content,
                                                                      timeout=timeout)

    def read_latest_ota_json_message(self, alias):
        if not self._log_collector_facade:
            logging.error("you should call set_filter firstly")
            return
        return self._log_collector_facade.read_latest_ota_json_message(alias)

    def read_system_trace_until(self, alias, expected_content, timeout):
        if not self._log_collector_facade:
            logging.error("you should call set_filter firstly")
            return
        return self._log_collector_facade.read_system_trace_until(alias_name=alias,
                                                                  expected_content=expected_content,
                                                                  timeout=timeout)

    def read_latest_system_trace(self, alias):
        if not self._log_collector_facade:
            logging.error("you should call set_filter firstly")
            return
        return self._log_collector_facade.read_latest_system_trace(alias)

    def read_ps_trace_until(self, alias, expected_content, timeout, **kwargs):
        if not self._log_collector_facade:
            logging.error("you should call set_filter firstly")
            return
        return self._log_collector_facade.read_ps_trace_until(alias_name=alias,
                                                              expected_content=expected_content,
                                                              timeout=timeout, **kwargs)

    def read_latest_ps_trace(self, alias, **kwargs):
        if not self._log_collector_facade:
            logging.error("you should call set_filter firstly")
            return
        return self._log_collector_facade.read_latest_ps_trace(alias, **kwargs)

    def read_raw_string_until(self, alias, expected_content, timeout, **kwargs):
        if not self._log_collector_facade:
            logging.error("you should call set_filter firstly")
            return
        return self._log_collector_facade.read_raw_string_until(alias_name=alias,
                                                                expected_content=expected_content,
                                                                timeout=timeout, **kwargs)

    def read_latest_raw_string(self, alias, **kwargs):
        if not self._log_collector_facade:
            logging.error("you should call set_filter firstly")
            return
        return self._log_collector_facade.read_latest_raw_string(alias, **kwargs)


class WindowsMTKPNPCOM(object):

    @staticmethod
    def _scan():
        pnp_info = subprocess.Popen("wmic path Win32_PnPEntity", shell=True, stdout=subprocess.PIPE).stdout.read()
        lines = pnp_info.decode('utf-8', errors='ignore').split("\n")

        name_key = r'^\s+(.+?)\s\(COM(\d+)\).*VID_0E8D'
        pattern = re.compile(name_key)
        ports = {}
        for line in lines:
            result = pattern.search(line)
            if result:
                ports[result.groups()[0]] = result.groups()[1]
        return ports

    def ports_ready(self, port_names):
        """
        port_names can be a embedded iterable object, e.g.
        [(portname1, portname2), portname3]
        in the sub iterable object (portname1, portname2), the logic is and
        between the top items (portname1, portname2) and portname3, the logic is or
        """
        if not port_names:
            # indicates no port need be checked
            logging.info('no port need be checked at all')
            return True

        ports = self._scan()
        if not ports:
            logging.error('no port of MTK was detected at all')
            return False

        # or for top items, and for subitems
        for port_group_need_check in port_names:
            if self._match_port_group(port_group_need_check, ports.keys()):
                return True
        return False

    def _match_port_group(self, port_group_need_check, existing_ports):
        # and operation, all must be hit
        if isinstance(port_group_need_check, six.string_types):
            return port_group_need_check in existing_ports
        elif hasattr(port_group_need_check, '__iter__'):
            # follow 'and' rule
            return self._match_port_group_with_items_under_and_rule(port_group_need_check, existing_ports)

        raise Exception('port(s) need be checked are not string or iterable, port(s): {}'.format(port_group_need_check))

    @staticmethod
    def _match_port_group_with_items_under_and_rule(port_group_need_check, existing_ports):
        for port_name in port_group_need_check:
            if port_name not in existing_ports:
                return False
        return True

    def get_logging_port_no(self):
        ports = self._scan()
        return ports.get('USB Debug Port', -1)
